#!/bin/bash
set -e
cd ~/localloop

echo "🌿 Local Loop — fixing r2 commits..."

decode_b64() {
  if base64 --version 2>&1 | grep -q GNU; then
    echo "$1" | base64 --decode
  else
    echo "$1" | base64 -d
  fi
}

echo "📝 Writing listings/[id] detail page..."
mkdir -p 'app/listings/[id]'
decode_b64 "" > 'app/listings/[id]/page.tsx'
git add -- 'app/listings/[id]/page.tsx'
git commit -m "Add listing detail page with photo gallery and messaging"
git push
echo "✓ listings/[id]/page.tsx committed"

echo "📝 Writing auth/pending page..."
mkdir -p app/auth/pending
decode_b64 "" > app/auth/pending/page.tsx
git add app/auth/pending/page.tsx
git commit -m "Add pending approval page"
git push
echo "✓ auth/pending/page.tsx committed"

echo "📝 Updating listings/new with approval gate..."
decode_b64 "" > app/listings/new/page.tsx
git add app/listings/new/page.tsx
git commit -m "Gate new listing page to approved members only"
git push
echo "✓ listings/new/page.tsx updated"

echo "📝 Writing messages inbox..."
mkdir -p app/messages
decode_b64 "" > app/messages/page.tsx
git add app/messages/page.tsx
git commit -m "Add messages inbox and sent views"
git push
echo "✓ messages/page.tsx committed"

echo ""
echo "🎉 All r2 files committed and pushed!"
